 a.attisdropped),CASE WHEN c.relkind IN ('v','m') THEN pg_get_viewdef(c.oid,true) ELSE NULL END) ORDER BY c.oid) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_%' AND c.relkind IN ('r','S','v','m','f')),(SELECT jsonb_agg(jsonb_build_array(p.oid,p.proowner,p.proacl,p.prosecdef,p.proconfig,pg_get_functiondef(p.oid)) ORDER BY p.oid) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_%' AND p.prokind IN ('f','p')),(SELECT jsonb_agg(jsonb_build_array(n.oid,n.nspowner,n.nspacl) ORDER BY n.oid) FROM pg_namespace n),(SELECT jsonb_agg(to_jsonb(m) ORDER BY m.roleid,m.member) FROM pg_auth_members m))::text),'counts',(SELECT jsonb_object_agg(name,n ORDER BY name) FROM (SELECT 'public.users' name, count(*) n FROM public.users UNION ALL SELECT 'public.seasons' name, count(*) n FROM public.seasons UNION ALL SELECT 'public.teams' name, count(*) n FROM public.teams UNION ALL SELECT 'public.standings' name, count(*) n FROM public.standings UNION ALL SELECT 'public.brackets' name, count(*) n FROM public.brackets UNION ALL SELECT 'public.matches' name, count(*) n FROM public.matches UNION ALL SELECT 'public.bracket_scores' name, count(*) n FROM public.bracket_scores UNION ALL SELECT 'public.leagues' name, count(*) n FROM public.leagues UNION ALL SELECT 'public.league_members' name, count(*) n FROM public.league_members UNION ALL SELECT 'public.password_resets' name, count(*) n FROM public.password_resets UNION ALL SELECT 'public.leaderboard_history' name, count(*) n FROM public.leaderboard_history UNION ALL SELECT 'public.leaderboard_history_snapshots' name, count(*) n FROM public.leaderboard_history_snapshots UNION ALL SELECT 'public.leaderboard_history_rows' name, count(*) n FROM public.leaderboard_history_rows) counts)) evidence) SELECT jsonb_build_object('snapshot',evidence,'defaults_match',e